planChart.mermaid:
flowchart LR
  A([draw runs]) --> B{in the title state?}
  B -- yes --> C[[draw the title screen]]
  C --> D{space pressed?}
  D -- yes --> E[switch to play]
  D -- no --> Z([end of frame])
  E --> Z
  B -- no --> F{in the play state?}
  F -- yes --> G[[update the game]]
  G --> H{player dead?}
  H -- yes --> I[switch to gameover]
  H -- no --> Z
  I --> Z
  F -- no --> M{in the gameover state?}
  M -- yes --> J[[draw the game over screen]]
  M -- no --> Z
  J --> K{r pressed?}
  K -- yes --> L[switch to title]
  K -- no --> Z
  L --> Z
